import React, { useState, useEffect } from 'react';
import { useNavigate } from "react-router-dom";

const Gallery = () => {
    const navigate = useNavigate();

    const [products, setProducts] = useState([]);
    const [error, setError] = useState("");
    const [currentPage, setCurrentPage] = useState(1);
    const productsPerPage = 6;
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetch('http://localhost:5000/api/products')
            .then(response => response.json())
            .then(data => {
                console.log("Fetched data:", data);
                const productArray = Array.isArray(data) ? data : data.products || [];
                setProducts(productArray);
                setLoading(false);
            })
            .catch(error => {
                console.error("Error fetching products:", error);
                setError("Failed to load products.");
                setLoading(false);
            });
    }, []);

    const handleOrderClick = (product) => {
        navigate(`/customers/order/${product.id}`);
    };

    if (loading) return <p className="text-center mt-10">Loading...</p>;
    if (error) return <p className="text-center text-red-500 mt-10">{error}</p>;

    // Pagination logic
    const indexOfLast = currentPage * productsPerPage;
    const indexOfFirst = indexOfLast - productsPerPage;
    const currentProducts = products.slice(indexOfFirst, indexOfLast);
    const totalPages = Math.ceil(products.length / productsPerPage);

    const handlePrevPage = () => {
        if (currentPage > 1) {
            setCurrentPage(prev => prev - 1);
        }
    };

    const handleNextPage = () => {
        if (currentPage < totalPages) {
            setCurrentPage(prev => prev + 1);
        }
    };

    return (
        <div className="max-w-7xl mx-auto px-4 py-8">
            <h1 className="text-3xl font-bold text-center mb-4">Gallery</h1>
            <p className="text-center text-gray-600 mb-8">Kindly go through the pictures of our carpets and canopy brands.</p>

            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6">
                {currentProducts.length === 0 ? (
                    <p className="text-center col-span-full">No products found.</p>
                ) : (
                    currentProducts.map(product => (
                        <div key={product.id} className="border rounded-lg shadow-md overflow-hidden hover:shadow-lg transition duration-300">
                            <img src={`http://localhost:5000${product.image_url}`} alt={product.name} className="w-full h-48 object-cover" />
                            <div className="p-4">
                                <h2 className="text-lg font-semibold">{product.name}</h2>
                                <p className="text-sm text-gray-600 mb-2">{product.description}</p>
                                <p className="font-bold text-blue-600 mb-4">₦{product.price}</p>
                                <button
                                    className="w-full px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700"
                                    onClick={() => handleOrderClick(product)}
                                >
                                    Order Now
                                </button>
                            </div>
                        </div>
                    ))
                )}
            </div>

            {/* Pagination Controls */}
            <div className="flex justify-center items-center gap-4 mt-10">
                <button
                    onClick={handlePrevPage}
                    disabled={currentPage === 1}
                    className="px-4 py-2 bg-blue-500 text-white rounded disabled:opacity-50"
                >
                    Previous
                </button>
                <span className="text-sm">Page {currentPage} of {totalPages}</span>
                <button
                    onClick={handleNextPage}
                    disabled={currentPage === totalPages}
                    className="px-4 py-2 bg-blue-500 text-white rounded disabled:opacity-50"
                >
                    Next
                </button>
            </div>
        </div>
    );
};

export default Gallery;
